import { useErrorBoundary } from '@suspensive/react';
import { FormProvider, useForm } from 'react-hook-form';
import { useSearchParams } from 'react-router-dom';
import { 금액확인Context } from '~/widgets/exchange-remittance-funnel/model/schemas';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useSelectedWalletAutoOnRamp } from '~/entities/user/lib/use-selected-wallet-auto-on-ramp';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import { YesOrNo } from '~/shared/api/dtos/enums';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

type Props = {
  context: 금액확인Context;
  onNext: (params: 금액확인Context) => void;
  onError: (error: Error) => void;
};

export const InputConfirmPage = ({ context, onNext, onError }: Props) => {
  const { openPinBottomSheet } = usePinBottomSheet();
  const { openAlertDialog } = useAlertDialog();
  const { setError } = useErrorBoundary();
  const { data: userRes } = useGetUserInfoQuery();
  const { autoOnRamp } = useSelectedWalletAutoOnRamp();
  const [searchParams] = useSearchParams();
  const isRefund = searchParams.get('isRefund');

  const { shortBankName: tokenBankLabel } = useComBankInfo(context.walletInsttCd ?? '');
  const form = useForm();

  const handleSubmit = form.handleSubmit(async () => {
    if (isRefund && autoOnRamp === YesOrNo.아니오) {
      openAlertDialog({
        message: i18n.t('text:setAutoOnRampRequired'),
        buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
        onConfirmClick: () => {
          if (window.ReactNativeWebView) {
            window.webViewBridge.send(NativeFunction.RootNavigation, PATHS.setAutoOnOffRamp.root);
            window.setTimeout(() => {
              window.webViewBridge.send(NativeFunction.GoBack);
            }, 0);
            return;
          }

          window.opener?.postMessage(
            {
              type: 'CBDC_NAVIGATE',
              path: PATHS.setAutoOnOffRamp.root,
            },
            window.location.origin,
          );
          window.setTimeout(() => window.close(), 0);
        },
        onCancelClick: () => {
          closeDialog(() => {
            openAlertDialog({
              message: i18n.t('text:failedInsufficientBalance'),
              onConfirmClick: () => {
                if (window.ReactNativeWebView) {
                  window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'CLOSE_POPUP' }));
                } else {
                  window.close();
                }
              },
            });
          });
        },
      });
      return;
    }

    if (context.txCd) {
      openPinBottomSheet((close) => {
        close();
        setTimeout(() => {
          onNext({
            ...context,
          });
        }, 0);
      });
    }
  });

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  return (
    <FormProvider {...form}>
      <div className="wrap bgw">
        <div className="content sub has-btm-btn">
          <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Confirm} transactionLabel={transactionLabel}>
            <div className="whitespace-pre-wrap">
              {i18n.t('text:linkedAccountFromAAndBToCAndD', {
                a: userRes?.tbCstmrMastr?.bankNm || '',
                b: userRes?.tbCstmrMastr?.realAcnutNo || '',
                c: context.personNm || '',
                d: tokenBankLabel || '',
              })}
            </div>
          </ConfirmInfo>
        </div>
        <div className="btm-btn-area" id="confirm-btn-area">
          <button type="button" className="btm-btn app" id="confirm-btn" onClick={handleSubmit}>
            {transactionLabel}하기
          </button>
        </div>
      </div>
    </FormProvider>
  );
};
